def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Determine where the field ends
        if i == len(line):
            # End of line
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            field = ''
            i += 1
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote or the closing quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        # Check what follows: comma or end of line
                        if i == len(line):
                            # End of line
                            fields.append(field)
                            break
                        elif line[i] == ',':
                            # Comma follows
                            fields.append(field)
                            i += 1
                            break
                        else:
                            # Invalid character after closing quote
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i < len(line):
                # Consume the comma
                i += 1

    return fields

